// NOTE: This entire module was generated by an LLM as a pure-Rust port of ICU4C's
// `UCharsTrieBuilder` (`ucharstriebuilder.h` / `ucharstriebuilder.cpp`) and its base
// class `StringTrieBuilder` (`stringtriebuilder.h` / `stringtriebuilder.cpp`), using
// the compact (`USTRINGTRIE_BUILD_SMALL`) construction algorithm.
//
// Summary of design decisions and implementation rationale:
//
// 1. Input Sorting & Deduplication (`BTreeMap<Vec<u16>, i32>`):
//    In ICU4C, `UCharsTrieBuilder` appends all strings into a single `UnicodeString`
//    buffer and sorts an array of `UCharsTrieElement` descriptors before building,
//    using unsigned 16-bit code unit lexicographical order (`compareStringTo`).
//    Here, `Char16TrieBuilder` stores entries in a `BTreeMap<Vec<u16>, i32>`, which
//    automatically maintains unique keys in `[u16]` lexicographical order and
//    eliminates the need for a separate string pool or custom sort/dedup pass.
//
// 2. Flattening the C++ Node Hierarchy (`NodeKind` + Arena):
//    ICU4C models the trie DAG during `USTRINGTRIE_BUILD_SMALL` using a polymorphic
//    C++ class hierarchy (`Node`, `FinalValueNode`, `ValueNode`, `IntermediateValueNode`,
//    `LinearMatchNode`, `UCTLinearMatchNode`, `BranchNode`, `ListBranchNode`,
//    `SplitBranchNode`, `BranchHeadNode`) allocated on the heap and deduplicated via
//    a `UHashtable`.
//    - Because `UCharsTrieBuilder::matchNodesCanHaveValues()` is always `true` (unlike
//      `BytesTrieBuilder`, where linear-match and branch-head nodes cannot encode
//      intermediate values directly), `IntermediateValueNode` is never instantiated
//      for 16-bit tries and is omitted.
//    - The remaining 5 concrete node types are represented by a `Copy` enum
//      `NodeKind<'a>` stored in a flat arena (`Vec<Node<'a>>`) and referenced by
//      index (`NodeId(usize)`).
//    - A `ListBranchNode` has at most `MAX_BRANCH_LINEAR_SUB_NODE_LENGTH` (5) entries;
//      storing `entries: [(u16, BranchTarget); 5]` inline with a `length: u8` and
//      canonical zeroed trailing slots keeps `NodeKind` `Copy` and avoids per-node
//      heap allocations.
//
// 3. Deterministic DAG Deduplication (`BTreeMap<NodeKind<'a>, NodeId>`):
//    In ICU4C, `UHashtable` (`uhash_find` / `uhash_puti`) is only used as a set to
//    intern structurally identical bottom-up nodes (`registerNode` / `registerFinalValue`);
//    the hash table is never iterated over, and both `markRightEdgesFirst` and `write`
//    traverse the DAG deterministically starting from `root`. Because child `NodeId`s
//    are interned bottom-up before their parent node is constructed, two nodes are
//    structurally identical if and only if their `NodeKind<'a>` values are equal.
//    Using `BTreeMap<NodeKind<'a>, NodeId>` provides exact structural deduplication in
//    `no_std + alloc` without requiring `HashMap` or porting ICU4C's `ustr_hashUCharsN`
//    polynomial hash arithmetic.
//
// 4. Recursive `SplitBranch` Construction (`make_branch_sub_node`):
//    ICU4C's `makeBranchSubNode` uses fixed-size local stacks (`middleUnits[14]` and
//    `lessThan[14]`) to manually unroll tail recursion on the `greaterOrEqual` half
//    before wrapping the result in `SplitBranchNode`s in LIFO order. Because the
//    binary-search split depth over 16-bit units is bounded by
//    `ceil(log2(65536 / 5)) = 14`, expressing both `less_than` and `greater_or_equal`
//    as direct recursive calls produces the exact same node registration order and
//    DAG structure without auxiliary stack arrays.
//
// 5. Right-Edge Marking & Backwards Serialization (`mark_right_edges_first`, `write_node`):
//    In the `Char16Trie` binary format, branch nodes jump forward by positive deltas
//    to their target sub-nodes, except for the rightmost branch edge, which falls
//    through directly to the immediately following units without a jump.
//    - Consequently, the trie is serialized backwards (from the end of the `u16`
//      buffer toward the front) so that jump targets are already written and their
//      offsets are known when encoding jump deltas (`offset - jump_target`).
//    - When a deduplicated sub-node is shared across multiple branches, it cannot be
//      written early if it also lies along an unwritten rightmost fall-through edge.
//      `mark_right_edges_first` traverses rightmost edges first and stamps unvisited
//      nodes with decreasing negative edge numbers (`-1, -2, ...`). During
//      serialization, `write_unless_inside_right_edge` checks whether a sub-node's
//      negative edge number falls within the current branch's rightmost-edge range
//      `[last_right..=first_right]`; if so, writing is deferred until that right edge
//      is emitted inline. Once a node is written, its `offset` becomes positive.
//    - Instead of ICU4C's manual end-of-buffer cursor (`ucharsCapacity - ucharsLength`),
//      `CompactBuilder` appends units into `uchars: Vec<u16>` in reverse order
//      (`write_unit` pushes one unit; `write_slice` extends with `s.iter().rev()`) so
//      that `self.uchars.len()` equals `ucharsLength` at every step, and reverses the
//      `Vec<u16>` once at the end of `build()`.
//
// 6. Lint & Safety Constraints:
//    `icu_collections` denies `clippy::indexing_slicing`, `clippy::unwrap_used`,
//    `clippy::expect_used`, and `clippy::panic` in non-test code. All slice and arena
//    accesses are expressed via `.get()`, `.get_mut()`, `.split_last()`, and iterators
//    so that no lint suppressions are required.

use super::trie::{
    Char16Trie, MAX_BRANCH_LINEAR_SUB_NODE_LENGTH, MAX_LINEAR_MATCH_LENGTH, MAX_ONE_UNIT_DELTA,
    MAX_ONE_UNIT_NODE_VALUE, MAX_ONE_UNIT_VALUE, MIN_LINEAR_MATCH, MIN_TWO_UNIT_DELTA_LEAD,
    MIN_TWO_UNIT_NODE_VALUE_LEAD, MIN_TWO_UNIT_VALUE_LEAD, THREE_UNIT_DELTA_LEAD,
    THREE_UNIT_NODE_VALUE_LEAD, THREE_UNIT_VALUE_LEAD, VALUE_IS_FINAL,
};
use alloc::collections::BTreeMap;
use alloc::vec::Vec;
use zerovec::ZeroVec;

const MAX_TWO_UNIT_VALUE: i32 =
    (((THREE_UNIT_VALUE_LEAD - MIN_TWO_UNIT_VALUE_LEAD) as i32) << 16) - 1; // 0x3ffe_ffff
const MAX_TWO_UNIT_NODE_VALUE: i32 =
    (((THREE_UNIT_NODE_VALUE_LEAD - MIN_TWO_UNIT_NODE_VALUE_LEAD) as i32) << 10) - 1; // 0xfd_ffff
const MAX_TWO_UNIT_DELTA: usize =
    (((THREE_UNIT_DELTA_LEAD - MIN_TWO_UNIT_DELTA_LEAD) as usize) << 16) - 1; // 0x03fe_ffff

/// Builder for a [`Char16Trie`].
///
/// Maps sequences of 16-bit units (commonly UTF-16 code units) to 32-bit integer values,
/// serializing them into the compact [`Char16Trie`] format (corresponding to ICU4C's
/// `UCharsTrieBuilder` with `USTRINGTRIE_BUILD_SMALL`).
#[derive(Debug, Default, Clone)]
pub struct Char16TrieBuilder {
    elements: BTreeMap<Vec<u16>, i32>,
}

impl Char16TrieBuilder {
    /// Creates a new empty [`Char16TrieBuilder`].
    pub fn new() -> Self {
        Self::default()
    }

    /// Inserts a 16-bit code unit sequence and its associated value into the builder.
    ///
    /// If the key was already present, its value is updated.
    pub fn insert(&mut self, key: &[u16], value: i32) -> &mut Self {
        self.elements.insert(key.to_vec(), value);
        self
    }

    /// Inserts a UTF-8 string (encoded as UTF-16 code units) and its associated value
    /// into the builder.
    ///
    /// If the key was already present, its value is updated.
    pub fn insert_str(&mut self, key: &str, value: i32) -> &mut Self {
        self.elements.insert(key.encode_utf16().collect(), value);
        self
    }

    /// Builds the [`Char16Trie`].
    pub fn build(self) -> Char16Trie<'static> {
        if self.elements.is_empty() {
            return Char16Trie::new(ZeroVec::new());
        }
        let sorted_elements: Vec<(&[u16], i32)> = self
            .elements
            .iter()
            .map(|(k, &v)| (k.as_slice(), v))
            .collect();

        let mut builder = CompactBuilder::new(&sorted_elements);
        let root = builder.make_node(0, sorted_elements.len(), 0);
        builder.mark_right_edges_first(root, -1);
        builder.write_node(root);
        let mut uchars = builder.uchars;
        uchars.reverse();
        Char16Trie::new(ZeroVec::alloc_from_slice(&uchars))
    }
}

impl<K: AsRef<[u16]>> FromIterator<(K, i32)> for Char16TrieBuilder {
    fn from_iter<T: IntoIterator<Item = (K, i32)>>(iter: T) -> Self {
        let mut builder = Self::new();
        builder.extend(iter);
        builder
    }
}

impl<K: AsRef<[u16]>> Extend<(K, i32)> for Char16TrieBuilder {
    fn extend<T: IntoIterator<Item = (K, i32)>>(&mut self, iter: T) {
        for (k, v) in iter {
            self.insert(k.as_ref(), v);
        }
    }
}

#[derive(Copy, Clone, Debug, PartialEq, Eq, PartialOrd, Ord)]
struct NodeId(usize);

#[derive(Copy, Clone, Debug, PartialEq, Eq, PartialOrd, Ord)]
enum BranchTarget {
    FinalValue(i32),
    SubNode(NodeId),
}

#[derive(Copy, Clone, Debug, PartialEq, Eq, PartialOrd, Ord)]
enum NodeKind<'a> {
    FinalValue {
        value: i32,
    },
    LinearMatch {
        units: &'a [u16],
        next: NodeId,
        value: Option<i32>,
    },
    ListBranch {
        length: u8,
        entries: [(u16, BranchTarget); MAX_BRANCH_LINEAR_SUB_NODE_LENGTH],
    },
    SplitBranch {
        unit: u16,
        less_than: NodeId,
        greater_or_equal: NodeId,
    },
    BranchHead {
        length: usize,
        next: NodeId,
        value: Option<i32>,
    },
}

struct Node<'a> {
    kind: NodeKind<'a>,
    offset: i32,
    first_edge_number: i32,
}

struct CompactBuilder<'a> {
    elements: &'a [(&'a [u16], i32)],
    nodes: Vec<Node<'a>>,
    dedup: BTreeMap<NodeKind<'a>, NodeId>,
    /// Units written in reverse order; reversed at the end of `build()`.
    uchars: Vec<u16>,
}

impl<'a> CompactBuilder<'a> {
    fn new(elements: &'a [(&'a [u16], i32)]) -> Self {
        Self {
            elements,
            nodes: Vec::with_capacity(elements.len() * 2),
            dedup: BTreeMap::new(),
            uchars: Vec::new(),
        }
    }

    fn get_element_string(&self, i: usize) -> &'a [u16] {
        self.elements.get(i).map(|&(s, _)| s).unwrap_or(&[])
    }

    fn get_element_string_length(&self, i: usize) -> usize {
        self.get_element_string(i).len()
    }

    fn get_element_unit(&self, i: usize, unit_index: usize) -> u16 {
        self.get_element_string(i)
            .get(unit_index)
            .copied()
            .unwrap_or(0)
    }

    fn get_element_value(&self, i: usize) -> i32 {
        self.elements.get(i).map(|&(_, v)| v).unwrap_or(0)
    }

    fn get_element_units(&self, i: usize, unit_index: usize, length: usize) -> &'a [u16] {
        self.get_element_string(i)
            .get(unit_index..unit_index + length)
            .unwrap_or(&[])
    }

    fn get_limit_of_linear_match(&self, first: usize, last: usize, mut unit_index: usize) -> usize {
        let first_str = self.get_element_string(first);
        let last_str = self.get_element_string(last);
        let min_string_length = first_str.len();
        while {
            unit_index += 1;
            unit_index < min_string_length && first_str.get(unit_index) == last_str.get(unit_index)
        } {}
        unit_index
    }

    fn count_element_units(&self, start: usize, limit: usize, unit_index: usize) -> usize {
        let mut length = 0;
        let mut i = start;
        while i < limit {
            let unit = self.get_element_unit(i, unit_index);
            i += 1;
            while i < limit && unit == self.get_element_unit(i, unit_index) {
                i += 1;
            }
            length += 1;
        }
        length
    }

    fn skip_elements_by_some_units(
        &self,
        mut i: usize,
        unit_index: usize,
        mut count: usize,
    ) -> usize {
        while count > 0 {
            let unit = self.get_element_unit(i, unit_index);
            i += 1;
            while unit == self.get_element_unit(i, unit_index) {
                i += 1;
            }
            count -= 1;
        }
        i
    }

    fn index_of_element_with_next_unit(
        &self,
        mut i: usize,
        limit: usize,
        unit_index: usize,
        unit: u16,
    ) -> usize {
        while i < limit && unit == self.get_element_unit(i, unit_index) {
            i += 1;
        }
        i
    }

    fn register_node(&mut self, kind: NodeKind<'a>) -> NodeId {
        if let Some(&id) = self.dedup.get(&kind) {
            return id;
        }
        let id = NodeId(self.nodes.len());
        self.dedup.insert(kind, id);
        self.nodes.push(Node {
            kind,
            offset: 0,
            first_edge_number: 0,
        });
        id
    }

    fn make_node(&mut self, mut start: usize, limit: usize, unit_index: usize) -> NodeId {
        let mut value = None;
        if unit_index == self.get_element_string_length(start) {
            // An intermediate or final value.
            let v = self.get_element_value(start);
            start += 1;
            if start == limit {
                return self.register_node(NodeKind::FinalValue { value: v });
            }
            value = Some(v);
        }
        // Now all [start..limit[ strings are longer than unit_index.
        let min_unit = self.get_element_unit(start, unit_index);
        let max_unit = self.get_element_unit(limit - 1, unit_index);
        let node_kind = if min_unit == max_unit {
            // Linear-match node: All strings have the same character at unit_index.
            let mut last_unit_index = self.get_limit_of_linear_match(start, limit - 1, unit_index);
            let mut next_node = self.make_node(start, limit, last_unit_index);
            // Break the linear-match sequence into chunks of at most MAX_LINEAR_MATCH_LENGTH.
            let mut length = last_unit_index - unit_index;
            let max_linear_match_length = MAX_LINEAR_MATCH_LENGTH as usize;
            while length > max_linear_match_length {
                last_unit_index -= max_linear_match_length;
                length -= max_linear_match_length;
                let units = self.get_element_units(start, last_unit_index, max_linear_match_length);
                next_node = self.register_node(NodeKind::LinearMatch {
                    units,
                    next: next_node,
                    value: None,
                });
            }
            let units = self.get_element_units(start, unit_index, length);
            NodeKind::LinearMatch {
                units,
                next: next_node,
                value,
            }
        } else {
            // Branch node.
            let length = self.count_element_units(start, limit, unit_index);
            // length >= 2 because min_unit != max_unit.
            let sub_node = self.make_branch_sub_node(start, limit, unit_index, length);
            NodeKind::BranchHead {
                length,
                next: sub_node,
                value,
            }
        };
        self.register_node(node_kind)
    }

    fn make_branch_sub_node(
        &mut self,
        start: usize,
        limit: usize,
        unit_index: usize,
        length: usize,
    ) -> NodeId {
        if length > MAX_BRANCH_LINEAR_SUB_NODE_LENGTH {
            // Branch on the middle unit.
            let i = self.skip_elements_by_some_units(start, unit_index, length / 2);
            let middle_unit = self.get_element_unit(i, unit_index);
            let less_than = self.make_branch_sub_node(start, i, unit_index, length / 2);
            let greater_or_equal =
                self.make_branch_sub_node(i, limit, unit_index, length - length / 2);
            return self.register_node(NodeKind::SplitBranch {
                unit: middle_unit,
                less_than,
                greater_or_equal,
            });
        }

        let mut entries = [(0u16, BranchTarget::FinalValue(0)); MAX_BRANCH_LINEAR_SUB_NODE_LENGTH];
        let mut unit_number = 0;
        let mut current = start;
        while current < limit {
            let unit = self.get_element_unit(current, unit_index);
            let next_start =
                self.index_of_element_with_next_unit(current + 1, limit, unit_index, unit);
            let target = if current + 1 == next_start
                && unit_index + 1 == self.get_element_string_length(current)
            {
                BranchTarget::FinalValue(self.get_element_value(current))
            } else {
                BranchTarget::SubNode(self.make_node(current, next_start, unit_index + 1))
            };
            if let Some(slot) = entries.get_mut(unit_number) {
                *slot = (unit, target);
            }
            unit_number += 1;
            current = next_start;
        }
        self.register_node(NodeKind::ListBranch {
            length: unit_number as u8,
            entries,
        })
    }

    fn mark_right_edges_first(&mut self, node_id: NodeId, mut edge_number: i32) -> i32 {
        let Some(node) = self.nodes.get(node_id.0) else {
            return edge_number;
        };
        if node.offset != 0 {
            return edge_number;
        }
        let kind = node.kind;
        match kind {
            NodeKind::FinalValue { .. } => {
                if let Some(node) = self.nodes.get_mut(node_id.0) {
                    node.offset = edge_number;
                }
                edge_number
            }
            NodeKind::LinearMatch { next, .. } | NodeKind::BranchHead { next, .. } => {
                edge_number = self.mark_right_edges_first(next, edge_number);
                if let Some(node) = self.nodes.get_mut(node_id.0) {
                    node.offset = edge_number;
                }
                edge_number
            }
            NodeKind::ListBranch { length, entries } => {
                if let Some(node) = self.nodes.get_mut(node_id.0) {
                    node.first_edge_number = edge_number;
                }
                let mut step = 0;
                let active_entries = entries.get(..length as usize).unwrap_or(&[]);
                for &(_, target) in active_entries.iter().rev() {
                    if let BranchTarget::SubNode(edge) = target {
                        edge_number = self.mark_right_edges_first(edge, edge_number - step);
                    }
                    // For all but the rightmost edge, decrement the edge number.
                    step = 1;
                }
                if let Some(node) = self.nodes.get_mut(node_id.0) {
                    node.offset = edge_number;
                }
                edge_number
            }
            NodeKind::SplitBranch {
                less_than,
                greater_or_equal,
                ..
            } => {
                if let Some(node) = self.nodes.get_mut(node_id.0) {
                    node.first_edge_number = edge_number;
                }
                edge_number = self.mark_right_edges_first(greater_or_equal, edge_number);
                edge_number = self.mark_right_edges_first(less_than, edge_number - 1);
                if let Some(node) = self.nodes.get_mut(node_id.0) {
                    node.offset = edge_number;
                }
                edge_number
            }
        }
    }

    fn get_node_offset(&self, node_id: NodeId) -> i32 {
        self.nodes.get(node_id.0).map(|n| n.offset).unwrap_or(0)
    }

    fn set_node_offset(&mut self, node_id: NodeId, offset: i32) {
        if let Some(node) = self.nodes.get_mut(node_id.0) {
            node.offset = offset;
        }
    }

    fn write_unless_inside_right_edge(
        &mut self,
        node_id: NodeId,
        first_right: i32,
        last_right: i32,
    ) {
        // Note: Edge numbers are negative, last_right <= first_right.
        // If offset > 0 then this node and its sub-nodes have been written already
        // and we need not write them again.
        // If this node is part of the unwritten right branch edge,
        // then we wait until that is written.
        let offset = self.get_node_offset(node_id);
        if offset < 0 && (offset < last_right || first_right < offset) {
            self.write_node(node_id);
        }
    }

    fn write_node(&mut self, node_id: NodeId) {
        let Some(&Node {
            kind,
            first_edge_number,
            ..
        }) = self.nodes.get(node_id.0)
        else {
            return;
        };
        match kind {
            NodeKind::FinalValue { value } => {
                let offset = self.write_value_and_final(value, true);
                self.set_node_offset(node_id, offset);
            }
            NodeKind::LinearMatch { units, next, value } => {
                self.write_node(next);
                self.write_slice(units);
                let node_type = MIN_LINEAR_MATCH + (units.len() as u16) - 1;
                let offset = self.write_value_and_type(value, node_type);
                self.set_node_offset(node_id, offset);
            }
            NodeKind::ListBranch { length, entries } => {
                // Write the sub-nodes in reverse order: The jump lengths are deltas from
                // after their own positions, so if we wrote the minUnit sub-node first,
                // then its jump delta would be larger.
                // Instead we write the minUnit sub-node last, for a shorter delta.
                let active_entries = entries.get(..length as usize).unwrap_or(&[]);
                let Some((&(last_unit, last_target), preceding_entries)) =
                    active_entries.split_last()
                else {
                    return;
                };
                let right_edge_number = match last_target {
                    BranchTarget::FinalValue(_) => first_edge_number,
                    BranchTarget::SubNode(right_edge) => self.get_node_offset(right_edge),
                };
                for &(_, target) in preceding_entries.iter().rev() {
                    if let BranchTarget::SubNode(sub_node) = target {
                        self.write_unless_inside_right_edge(
                            sub_node,
                            first_edge_number,
                            right_edge_number,
                        );
                    }
                }
                // The maxUnit sub-node is written as the very last one because we do
                // not jump for it at all.
                match last_target {
                    BranchTarget::FinalValue(val) => {
                        self.write_value_and_final(val, true);
                    }
                    BranchTarget::SubNode(right_edge) => {
                        self.write_node(right_edge);
                    }
                }
                let mut offset = self.write_unit(last_unit);
                // Write the rest of this node's unit-value pairs.
                for &(unit, target) in preceding_entries.iter().rev() {
                    let (value, is_final) = match target {
                        BranchTarget::FinalValue(val) => (val, true),
                        BranchTarget::SubNode(sub_node) => {
                            let sub_offset = self.get_node_offset(sub_node);
                            debug_assert!(sub_offset > 0);
                            (offset - sub_offset, false)
                        }
                    };
                    self.write_value_and_final(value, is_final);
                    offset = self.write_unit(unit);
                }
                self.set_node_offset(node_id, offset);
            }
            NodeKind::SplitBranch {
                unit,
                less_than,
                greater_or_equal,
            } => {
                // Encode the less-than branch first.
                let ge_offset = self.get_node_offset(greater_or_equal);
                self.write_unless_inside_right_edge(less_than, first_edge_number, ge_offset);
                // Encode the greater-or-equal branch last because we do not jump for it at all.
                self.write_node(greater_or_equal);
                // Write this node.
                let lt_offset = self.get_node_offset(less_than);
                debug_assert!(lt_offset > 0);
                self.write_delta_to(lt_offset as usize);
                let offset = self.write_unit(unit);
                self.set_node_offset(node_id, offset);
            }
            NodeKind::BranchHead {
                length,
                next,
                value,
            } => {
                self.write_node(next);
                let offset = if length <= MIN_LINEAR_MATCH as usize {
                    self.write_value_and_type(value, (length - 1) as u16)
                } else {
                    self.write_unit((length - 1) as u16);
                    self.write_value_and_type(value, 0)
                };
                self.set_node_offset(node_id, offset);
            }
        }
    }

    fn write_unit(&mut self, unit: u16) -> i32 {
        self.uchars.push(unit);
        self.uchars.len() as i32
    }

    fn write_slice(&mut self, s: &[u16]) -> i32 {
        self.uchars.extend(s.iter().rev().copied());
        self.uchars.len() as i32
    }

    fn write_value_and_final(&mut self, i: i32, is_final: bool) -> i32 {
        let final_bit = if is_final { VALUE_IS_FINAL } else { 0 };
        if (0..=MAX_ONE_UNIT_VALUE as i32).contains(&i) {
            return self.write_unit((i as u16) | final_bit);
        }
        if !(0..=MAX_TWO_UNIT_VALUE).contains(&i) {
            let unit0 = THREE_UNIT_VALUE_LEAD | final_bit;
            let unit1 = ((i as u32) >> 16) as u16;
            let unit2 = i as u16;
            self.write_slice(&[unit0, unit1, unit2])
        } else {
            let unit0 = (MIN_TWO_UNIT_VALUE_LEAD + ((i >> 16) as u16)) | final_bit;
            let unit1 = i as u16;
            self.write_slice(&[unit0, unit1])
        }
    }

    fn write_value_and_type(&mut self, value: Option<i32>, node: u16) -> i32 {
        let Some(value) = value else {
            return self.write_unit(node);
        };
        if !(0..=MAX_TWO_UNIT_NODE_VALUE).contains(&value) {
            let unit0 = THREE_UNIT_NODE_VALUE_LEAD | node;
            let unit1 = ((value as u32) >> 16) as u16;
            let unit2 = value as u16;
            self.write_slice(&[unit0, unit1, unit2])
        } else if value <= MAX_ONE_UNIT_NODE_VALUE as i32 {
            let unit0 = (((value + 1) as u16) << 6) | node;
            self.write_unit(unit0)
        } else {
            let unit0 = (MIN_TWO_UNIT_NODE_VALUE_LEAD + (((value >> 10) as u16) & 0x7fc0)) | node;
            let unit1 = value as u16;
            self.write_slice(&[unit0, unit1])
        }
    }

    fn write_delta_to(&mut self, jump_target: usize) -> i32 {
        debug_assert!(self.uchars.len() >= jump_target);
        let i = self.uchars.len().saturating_sub(jump_target);
        if i <= MAX_ONE_UNIT_DELTA as usize {
            return self.write_unit(i as u16);
        }
        if i <= MAX_TWO_UNIT_DELTA {
            let unit0 = MIN_TWO_UNIT_DELTA_LEAD + ((i >> 16) as u16);
            let unit1 = i as u16;
            self.write_slice(&[unit0, unit1])
        } else {
            let unit0 = THREE_UNIT_DELTA_LEAD;
            let unit1 = (i >> 16) as u16;
            let unit2 = i as u16;
            self.write_slice(&[unit0, unit1, unit2])
        }
    }
}
